int count;
gid_t* group_list;

// Step 1: Determine the total number of groups
count = getgroups(0, NULL);
// Error check needed if count < 0

if (count > 0) {
    // Step 2: Allocate buffer
    group_list = malloc(sizeof(gid_t) * count);

    // Step 3: Populate the array
    if (group_list != NULL) {
        getgroups(count, group_list);

        // group_list now holds 'count' GIDs
        free(group_list);
    }
}
